    (void)in; (void)out;  /* sum-only: no zero-fill of out */
    break;

  case 1:
    __SIMD_fastunpack1_16_cscalar1_il(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_cscalar1_il(in, out, sum, a_block);
    break;

  case 3:
    __SIMD_fastunpack3_16_cscalar1_il(in, out, sum, a_block);
    break;

