  _bc = _mm256_set_m128i(_mm_blend_epi16(_mm_set1_epi16((short)a_block[62]), _mm_set1_epi16((short)a_block[63]), 0xF0), _mm_blend_epi16(_mm_set1_epi16((short)a_block[60]), _mm_set1_epi16((short)a_block[61]), 0xF0));
