    break;
  case 5:
    __SIMD_fastunpack5_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 6:
    __SIMD_fastunpack6_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 7:
    __SIMD_fastunpack7_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 8:
    __SIMD_fastunpack8_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 9:
    __SIMD_fastunpack9_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 10:
    __SIMD_fastunpack10_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 11:
    __SIMD_fastunpack11_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 12:
    __SIMD_fastunpack12_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 13:
    __SIMD_fastunpack13_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
