  case 14:
    __SIMD_fastunpack14_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
    break;
  case 15:
    __SIMD_fastunpack15_16_pfor_cquarter_il(in, out, sum, a_block, pex, bm16);
