static void simdunpack_u16_il_corrected_uniform_madd(const __m256i *in, uint16_t *out, const uint32_t bit, const __m256i anchor, __m256i* sum) {
  switch (bit) {
  case 0:
    /* b==0: every unpacked OutReg is 0; corrected OutReg = anchor.
       Aggregate anchor once per OutReg. */
    {
      size_t _k;
      for (_k = 0; _k < 16; ++_k) {
        aggregate_sums_u16_madd(anchor, sum);
      }
    }
    (void)in; (void)out;  /* sum-only: no zero-fill of out */
    break;

  case 1:
    __SIMD_fastunpack1_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 2:
    __SIMD_fastunpack2_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 3:
    __SIMD_fastunpack3_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 4:
    __SIMD_fastunpack4_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 5:
    __SIMD_fastunpack5_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 6:
    __SIMD_fastunpack6_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 7:
    __SIMD_fastunpack7_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 8:
    __SIMD_fastunpack8_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 9:
    __SIMD_fastunpack9_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 10:
    __SIMD_fastunpack10_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 11:
    __SIMD_fastunpack11_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 12:
    __SIMD_fastunpack12_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 13:
    __SIMD_fastunpack13_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 14:
    __SIMD_fastunpack14_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 15:
    __SIMD_fastunpack15_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  case 16:
    __SIMD_fastunpack16_16_corrected_uniform_madd_il(in, out, sum, anchor);
    break;

  default:
    break;
  }
}
