    break;

  case 1:
    __SIMD_fastunpack1_16_cscalar1_madd_il(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_cscalar1_madd_il(in, out, sum, a_block);
    break;

  case 3:
