    break;

  case 1:
    __SIMD_fastunpack1_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 3:
    __SIMD_fastunpack3_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 4:
