    break;

  case 7:
    __SIMD_fastunpack7_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 8:
    __SIMD_fastunpack8_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 9:
    __SIMD_fastunpack9_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 10:
    __SIMD_fastunpack10_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 11:
    __SIMD_fastunpack11_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 12:
    __SIMD_fastunpack12_16_cscalar3_madd_il(in, out, sum, a_block);
    break;

  case 13:
    __SIMD_fastunpack13_16_cscalar3_madd_il(in, out, sum, a_block);
