  case 12:
    __SIMD_fastunpack12_16_pfor_cscalar2_madd_il(in, out, sum, a_block, pex, bm16);
    break;
  case 13:
    __SIMD_fastunpack13_16_pfor_cscalar2_madd_il(in, out, sum, a_block, pex, bm16);
