    (void)in; (void)out;  /* sum-only: no zero-fill of out */
    break;

  case 1:
    __SIMD_fastunpack1_16_cscalar3_noagg_il(in, out, sum, a_block);
    break;

  case 2:
    __SIMD_fastunpack2_16_cscalar3_noagg_il(in, out, sum, a_block);
    break;

  case 3:
    __SIMD_fastunpack3_16_cscalar3_noagg_il(in, out, sum, a_block);
    break;

  case 4:
    __SIMD_fastunpack4_16_cscalar3_noagg_il(in, out, sum, a_block);
    break;

  case 5:
    __SIMD_fastunpack5_16_cscalar3_noagg_il(in, out, sum, a_block);
