  case 7:
    __SIMD_fastunpack7_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 8:
    __SIMD_fastunpack8_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
