  case 9:
    __SIMD_fastunpack9_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 10:
    __SIMD_fastunpack10_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
