  case 12:
    __SIMD_fastunpack12_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 13:
    __SIMD_fastunpack13_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 14:
    __SIMD_fastunpack14_16_cscalar1_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 15:
