    break;

  case 7:
    __SIMD_fastunpack7_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 8:
    __SIMD_fastunpack8_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 9:
    __SIMD_fastunpack9_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 10:
    __SIMD_fastunpack10_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 11:
    __SIMD_fastunpack11_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 12:
    __SIMD_fastunpack12_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 13:
    __SIMD_fastunpack13_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
    break;

  case 14:
    __SIMD_fastunpack14_16_cscalar2_nobc_il(in, out, sum, a_block, scalar_acc);
